INSERT INTO skills (user_id, name, description, instructions) VALUES (
  NULL,
  'skill-creator',
  'Create new skills and iteratively improve existing ones. Use when the user wants to create a skill from scratch, update or optimize an existing skill, or get help writing skill names, descriptions, and instructions.',
  E'# Skill Creator\n\nA skill for helping users create new skills.\n\n## Workflow\n\n1. Ask what the skill should do\n2. Suggest a name (gerund form, lowercase-hyphens, max 64 chars, e.g. analyzing-sales-data)\n3. Draft a description (third person, 1-2 sentences, includes what AND when to use)\n4. Draft instructions (markdown, concise, only add context the LLM doesn''t already have)\n5. Ask if the skill should be scoped to specific document folders\n6. Call save_skill to persist\n\n## Naming Rules\n- Lowercase letters, numbers, hyphens only\n- Max 64 characters\n- Gerund form preferred: analyzing-X, reviewing-X, managing-X\n\n## Description Rules\n- Write in third person (not "I can" or "You can")\n- Include WHAT the skill does AND WHEN to use it\n- Include specific key terms the LLM will match against\n- Min 20 chars, max 1024 chars\n\n## Instructions Rules\n- Only include context the LLM doesn''t already know\n- Use markdown: headings, code blocks, checklists\n- For complex skills, break into numbered steps\n- Keep concise — every token competes with conversation context'
);
